# spawnCoordinator.py
#
# Originally generated by Claude 11/2026
#
# Tiny population/birth registry for roaming children. 
#
# Run this ONCE, on the host named as COORDINATOR_HOST in roamConfig.py:
#
#   pip install flask
#   python3 spawnCoordinator.py
#
# Every child, on every host, talks to this one service to:
#   - register itself when it starts  (POST /register)
#   - prove it's still alive          (POST /heartbeat)
#   - check out when it dies          (POST /deregister)
#   - ask permission to replicate     (POST /spawn_request)
#
# Modified to be executed from o1.py alnog with some variable renaming
#

import time
import random
import threading

from flask import Flask, request, jsonify

import roamConfig

app = Flask(__name__)
lock = threading.Lock()

state = {
    "nextCellId": 2,   # cell 1 is always the original child1.py
    "registry": {},    # cellId -> {parent, baseFile, host, lastSeen}
}


def reapDeadChildren():
    """Drop any cell we haven't heard from in a while -- assume it crashed
    (or got kill -9'd) without calling /deregister, and free its slot.
    Caller must hold `lock`."""
    now = time.time()
    dead = [cid for cid, info in state["registry"].items()
            if now - info["lastSeen"] > roamConfig.HEARTBEAT_TIMEOUT]
    for cid in dead:
        print("Reaping stale cell (no heartbeat): ", cid, state["registry"][cid])
        del state["registry"][cid]


@app.route("/register", methods=["POST"])
def register():
    data = request.get_json()
    with lock:
        reapDeadChildren()
        state["registry"][data["childID"]] = {
            "parent": data.get("parent", ""),
            "baseFile": data.get("baseFile", ""),
            "host": data.get("host", ""),
            "lastSeen": time.time(),
        }
        pop = len(state["registry"])
    print("Registered child {} on {} (population now {})".format(
        data["childID"], data.get("host"), pop))
    return jsonify({"ok": True, "population": pop})


@app.route("/heartbeat", methods=["POST"])
def heartbeat():
    data = request.get_json()
    with lock:
        if data["childID"] in state["registry"]:
            state["registry"][data["childID"]]["lastSeen"] = time.time()
    return jsonify({"ok": True})


@app.route("/deregister", methods=["POST"])
def deregister():
    data = request.get_json()
    with lock:
        state["registry"].pop(data["childID"], None)
        pop = len(state["registry"])
    print("Deregistered child {} (population now {})".format(data["childID"], pop))
    return jsonify({"ok": True, "population": pop})


@app.route("/status", methods=["GET"])
def status():
    with lock:
        reapDeadChildren()
        pop = len(state["registry"])
        registry = dict(state["registry"])
    return jsonify({"population": pop, "registry": registry})

@app.route("/list_registry", methods=["GET"])
def list_registry():
    """Return every cell currently in the registry, each tagged with its ID."""
    with lock:
        reapDeadChildren()
        cells = [
            dict(info, childID=cid)
            for cid, info in state["registry"].items()
        ]
    return jsonify({"population": len(cells), "cells": cells})

@app.route("/spawn_request", methods=["POST"])
def spawn_request():
    data = request.get_json()
    maxPop = data["maxPop"]

    with lock:
        reapDeadChildren()
        pop = len(state["registry"])

        # Same "-5" safety margin the original toReplicate() used, since
        # there's an unavoidable lag between "spawn approved" and the child
        # actually registering itself.
        # REMOVED FOR TESTING
        #if pop >= (maxPop - 5):
        if pop >= (maxPop):
            print("Spawn refused, population {} at/near cap {}".format(pop, maxPop))
            return jsonify({"allow": False, "population": pop})

        childId = state["nextChildID"]
        state["nextChildID"] += 1

        targetHostName = random.choice(list(roamConfig.HOSTS.keys()))

        childBody = "child{}.py".format(childID)
        #childDNA = "cell{}DNA.py".format(cellId)

    print("Spawn approved: childID {} -> host {}".format(childID, targetHostName))
    return jsonify({
        "allow": True,
        "childID": childID,
        "childBody": childBody,
        #"childDNA": childDNA,
        "targetHost": targetHostName,
        "targetIP": roamConfig.HOSTS[targetHostName],
    })


if __name__ == "__main__":
    print("Spawn coordinator starting on port {}...".format(roamConfig.COORDINATOR_PORT))
    print("Known hosts: ", roamConfig.HOSTS)
    app.run(host="0.0.0.0", port=roamConfig.COORDINATOR_PORT, threaded=True)
